const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Black Sea geometry (central region)
  const blackSea = ee.Geometry.Polygon([
    [[30.0, 41.0], [42.0, 41.0], [42.0, 46.5], [30.0, 46.5], [30.0, 41.0]]
  ]);

  // 2. Cloud masking function for Sentinel-2
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Get data for May 20, 2022 (±3 days window)
  let mayCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(blackSea)
    .filterDate('2022-05-18', '2022-05-23')
    .map(maskClouds);

  let maySize = await mayCol.size().getInfo();
  console.log(`May images found: ${maySize}`);

  // Fallback to wider date range if needed
  if (maySize === 0) {
    mayCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(blackSea)
      .filterDate('2022-05-15', '2022-05-25')
      .map(maskClouds);
    maySize = await mayCol.size().getInfo();
    console.log(`May images (wider range): ${maySize}`);
  }

  // 4. Get data for June 20, 2022 (±3 days window)
  let juneCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(blackSea)
    .filterDate('2022-06-18', '2022-06-23')
    .map(maskClouds);

  let juneSize = await juneCol.size().getInfo();
  console.log(`June images found: ${juneSize}`);

  // Fallback to wider date range if needed
  if (juneSize === 0) {
    juneCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(blackSea)
      .filterDate('2022-06-15', '2022-06-25')
      .map(maskClouds);
    juneSize = await juneCol.size().getInfo();
    console.log(`June images (wider range): ${juneSize}`);
  }

  if (maySize === 0 || juneSize === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate mean brightness (use visible bands B2,B3,B4)
  const mayImg = mayCol.median().select(['B2', 'B3', 'B4']);
  const juneImg = juneCol.median().select(['B2', 'B3', 'B4']);

  // Calculate mean brightness as average of RGB bands
  const mayBrightness = mayImg.reduce(ee.Reducer.mean());
  const juneBrightness = juneImg.reduce(ee.Reducer.mean());

  // 6. Check pixel counts
  const mayCount = await mayBrightness.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: blackSea,
    scale: 3000,
    maxPixels: 1e9
  }).get('B2_mean').getInfo();

  const juneCount = await juneBrightness.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: blackSea,
    scale: 3000,
    maxPixels: 1e9
  }).get('B2_mean').getInfo();

  console.log(`May valid pixels: ${mayCount}, June valid pixels: ${juneCount}`);

  if (mayCount === 0 || juneCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Get mean values
  const mayVal = await mayBrightness.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: blackSea,
    scale: 3000,
    maxPixels: 1e9
  }).get('B2_mean').getInfo();

  const juneVal = await juneBrightness.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: blackSea,
    scale: 3000,
    maxPixels: 1e9
  }).get('B2_mean').getInfo();

  console.log(`May brightness: ${mayVal}, June brightness: ${juneVal}`);

  // 8. Validate and answer
  if (mayVal === null || juneVal === null || isNaN(mayVal) || isNaN(juneVal)) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (mayVal < 0 || juneVal < 0 || mayVal > 10000 || juneVal > 10000) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (juneVal > mayVal) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
